import openpyxl

wb = openpyxl.load_workbook('budget.xlsx', data_only=True)
for ws in wb.worksheets:
    print(f"=== Sheet: {ws.title} (dims={ws.dimensions}) ===")
    for row in ws.iter_rows():
        vals = []
        for c in row:
            if c.value is not None:
                vals.append(f"{c.coordinate}={c.value!r}")
        if vals:
            print(" | ".join(vals))

from openpyxl import load_workbook

wb = load_workbook('budget.xlsx', data_only=True, read_only=True)
for ws in wb.worksheets:
    print(f"SHEET: {ws.title}")
    for row in ws.iter_rows():
        cells = [(c.coordinate, c.value) for c in row if c.value is not None]
        if cells:
            print(cells)

import sys
from openpyxl import load_workbook

path = "budget.xlsx"
wb = load_workbook(path, data_only=False)
print("Sheets:", wb.sheetnames)
for ws in wb.worksheets:
    print(f"\n=== Sheet: {ws.title} (dims {ws.dimensions}, max_row={ws.max_row}, max_col={ws.max_column}) ===")
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                print(f"{cell.coordinate}: {cell.value!r}")

from openpyxl import load_workbook
wb = load_workbook('budget.xlsx', data_only=True)
total = 0
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if isinstance(c.value, (int, float)):
                total += c.value
open('budget_total.txt', 'w').write(str(total))

